begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(16);
select is((select count(*)::integer from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and not c.relrowsecurity),0,'todas las tablas públicas tienen RLS');
select is((select count(*)::integer from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and c.relname not in ('pvpc_days','pvpc_intervals') and has_table_privilege('anon',c.oid,'select')),0,'anónimo no lee tablas privadas');
select is((select count(*)::integer from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and c.relname not in ('appliances','notification_preferences') and (has_table_privilege('authenticated',c.oid,'insert') or has_table_privilege('authenticated',c.oid,'update') or has_table_privilege('authenticated',c.oid,'delete'))),0,'escritura cliente limitada a tablas autorizadas');
select is((select count(*)::integer from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prosecdef and has_function_privilege('anon',p.oid,'execute')),0,'anónimo no invoca funciones privilegiadas');
select is((select count(*)::integer from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prosecdef and not exists(select 1 from unnest(coalesce(p.proconfig,array[]::text[])) x where x like 'search_path=%')),0,'funciones privilegiadas fijan search_path');
insert into auth.users(id,email,email_confirmed_at) values ('00000000-0000-0000-0000-0000000000a1','surface-a@example.invalid',now()),('00000000-0000-0000-0000-0000000000c1','surface-c@example.invalid',now());
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-0000000000a1',true);
set local role authenticated;
do $$begin perform set_config('test.surface_h1',public.create_household('H1 superficie')::text,true);end$$;
insert into public.appliances(household_id,name,duration_minutes,energy_kwh) values(current_setting('test.surface_h1')::uuid,'Privado',60,1);
insert into public.notification_preferences(household_id,user_id,preferences) values(current_setting('test.surface_h1')::uuid,auth.uid(),'{}');
reset role;
insert into public.plans(id,household_id,created_by,snapshot) values('00000000-0000-0000-0000-0000000000b1',current_setting('test.surface_h1')::uuid,'00000000-0000-0000-0000-0000000000a1','{}');
insert into public.usage_logs(household_id,plan_id,confirmed_by,snapshot) values(current_setting('test.surface_h1')::uuid,'00000000-0000-0000-0000-0000000000b1','00000000-0000-0000-0000-0000000000a1','{}');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-0000000000c1',true);
set local role authenticated;
select is((select count(*)::integer from public.households where id=current_setting('test.surface_h1')::uuid),0,'C no lee hogar A');
select is((select count(*)::integer from public.household_memberships where household_id=current_setting('test.surface_h1')::uuid),0,'C no lee miembros A');
select is((select count(*)::integer from public.appliances where household_id=current_setting('test.surface_h1')::uuid),0,'C no lee aparatos A');
select is((select count(*)::integer from public.plans where household_id=current_setting('test.surface_h1')::uuid),0,'C no lee planes A');
select is((select count(*)::integer from public.usage_logs where household_id=current_setting('test.surface_h1')::uuid),0,'C no lee usos A');
select is((select count(*)::integer from public.notification_preferences where household_id=current_setting('test.surface_h1')::uuid),0,'C no lee preferencias A');
select throws_ok($$insert into public.notification_preferences(household_id,user_id,preferences) values(current_setting('test.surface_h1')::uuid,auth.uid(),'{}')$$,'42501',null,'C no crea preferencias en hogar A');
select is_empty($$update public.appliances set name='Ataque' where household_id=current_setting('test.surface_h1')::uuid returning id$$,'C no modifica aparatos A');
select throws_ok($$select * from public.telegram_link_nonces$$,'42501',null,'cliente no lee nonces');
select throws_ok($$select * from public.plan_audit_events$$,'42501',null,'cliente no lee auditoría privada');
select throws_ok($$select * from public.job_runs$$,'42501',null,'cliente no lee jobs privados');
reset role;select * from finish();rollback;
